"""Role-aware browser storage-state helpers."""

from __future__ import annotations

from collections.abc import Mapping
import os
from pathlib import Path
import re


AUTH_DIRECTORY = Path("playwright/.auth")
PROJECT_ROOT = Path(__file__).resolve().parents[2]
ROLE_PATTERN = re.compile(r"^[a-z][a-z0-9_-]*$")


def normalize_auth_role(role: str) -> str:
    """Normalize a role used in file names and environment variable names."""
    normalized = role.strip().lower()
    if not ROLE_PATTERN.fullmatch(normalized):
        raise RuntimeError(f"Invalid QA auth role: {role}")
    return normalized


def configured_auth_roles(
    environment: Mapping[str, str] | None = None,
) -> list[str]:
    """Read unique auth roles from QA_AUTH_ROLES."""
    values = environment if environment is not None else os.environ
    configured = values.get("QA_AUTH_ROLES", "").strip()
    if not configured:
        return []
    return list(dict.fromkeys(
        normalize_auth_role(role)
        for role in configured.split(",")
        if role.strip()
    ))


def selected_auth_role(
    environment: Mapping[str, str] | None = None,
) -> str:
    """Return the role used by the default browser context."""
    values = environment if environment is not None else os.environ
    roles = configured_auth_roles(values)
    requested = values.get("QA_AUTH_ROLE", "").strip()
    selected = normalize_auth_role(requested or (roles[0] if roles else "user"))
    if roles and selected not in roles:
        raise RuntimeError(
            f"QA_AUTH_ROLE must be one of QA_AUTH_ROLES: {', '.join(roles)}"
        )
    return selected


def auth_role_variable(role: str, suffix: str) -> str:
    """Build one role credential variable name, for example QA_AUTH_ADMIN_USERNAME."""
    normalized = normalize_auth_role(role).replace("-", "_")
    return f"QA_AUTH_{normalized.upper()}_{suffix}"


def auth_credentials(
    role: str,
    environment: Mapping[str, str] | None = None,
) -> tuple[str, str]:
    """Read one role's username and password."""
    values = environment if environment is not None else os.environ
    username_variable = auth_role_variable(role, "USERNAME")
    password_variable = auth_role_variable(role, "PASSWORD")
    username = values.get(username_variable, "").strip()
    password = values.get(password_variable, "")
    if not username or not password:
        raise RuntimeError(
            f"Missing auth credentials: {username_variable} and "
            f"{password_variable}"
        )
    return username, password


def auth_state_path(
    role: str,
    environment: Mapping[str, str] | None = None,
    project_root: Path = PROJECT_ROOT,
) -> Path:
    """Resolve one role's ignored storage state file."""
    values = environment if environment is not None else os.environ
    normalized = normalize_auth_role(role)
    manual_state = values.get("QA_AUTH_STATE", "").strip()
    if manual_state and normalized == selected_auth_role(values):
        return (project_root / manual_state).resolve()
    return (project_root / AUTH_DIRECTORY / f"{normalized}.json").resolve()


def require_auth_state(
    role: str,
    environment: Mapping[str, str] | None = None,
    project_root: Path = PROJECT_ROOT,
) -> Path:
    """Require a state file generated by scripts/auth_state.py."""
    state_path = auth_state_path(role, environment, project_root)
    if not state_path.is_file():
        raise RuntimeError(
            f"Auth state does not exist: {state_path}. "
            "Run python scripts/auth_state.py first."
        )
    return state_path
